urce reviewed separately, unchanged matching legal consumption; all original DB read only. Initial add-test script naming assertion prevented edits; http-red-r1 is old29 baseline, NOT RED evidence. Actual http-red-r2:13failed28pass. Minimumimplementation specialized100PASS; successfulDTO extra and cumulative134PASS.\\n\\n\\nFILE .evidence/qyh-creator-lifecycle-read-admission-20261014/routing-implementation-plan.md SHA256 3674c9cdd4f8497dd1b3749aea75659d19d67cbbe44b766810967e7b3209efe9\\n# 生命周期GET兼容接线精确方案\\n\\nRules/base2029/sameowner/14:00UTC及原Scope不变。专用bounded-reader Task另持有新模块/测试，codequality仍待；routerTask只持有router/read_http/evidence/D-wave。完整Goal和原边界持续。\\n\\n修改router：import新Reader/Error，新增lazy factory与Annotated dependency；现_require_creator_growth_installation仅return原_invoke结果、注解改原EcommerceWorkshopModuleReadinessResponse，其余既有调用者仍忽略，不重复scope/hash算法。只有本GET改ReadCatalogDependency并接readonly reader。先query参数拒绝再原安装/role/markings/dataScope校验；admission须为原类型，其item.blockers含server INSTALLED_ASSET_READONLY才调用newReader.read(scope)，没有marker的合法legacy仍调用原service.view(scope)；错型None不回退，以503显式READ_ADMISSION_UNAVAILABLE失败关闭。新Reader固定错误code映射503固定中文message，不回0DTO。不能HTTP传mode、limits、SQL、installation或Role判运行权限。所有POST/start/observations/freeze/别的GET完全不改。\\n\\n测试read_http：原未知GET样例lifecycle换到creator workflow/drafts、精确readGET白名单加此一项；新增admitted readonly只调用新reader、legacy合法旧view保持、query400/denybeforeanyread、错型admission503、newReaderError503且无empty成功、全部其他POST/GET型式门保持。完整prospective diff在freeze材料；尚未实施，不拿计划当GREEN。\\n\\n先独立plan合法消费，再RED/minimal/read_http/read_catalog/bounded-reader/lifecycle/store/tenant相邻与typechecks。bounded模块完整native fixture/quality必须已合法覆盖同source，四source整体复核，最新已提交gitarchive/API只读正常场景验证；原真人同受控认证/metadata真实GET/root菜单及按原稿1440/1280/1920、503和原650指纹。legacy行为不测试真实写，原所有业务命令不点击。然后代码/现场Prime准确各slice Delivery/Authority/Prime，不能跨基线复用。原schema161/650/HostworkerProviderOFF，原Budget C、人最后批准、Source/自然链/安装/八场景/visualP1/观察发布仍未完成。\\n\\n\\nFILE .evidence/qyh-creator-lifecycle-read-admission-20261014/plan-review-consumption-r3.json SHA256 98d5f1e951921cbd4dcf76d622a6982a62c56c656f9ac25eed9805255c248f62\\n{\\n  \\\"schema\\\": \\\"aos-material-review-consumption/v1\\\",\\n  \\\"request_id\\\": \\\"qyh-creator-lifecycle-read-admission-20261014-plan-r3\\\",\\n  \\\"task_id\\\": \\\"qyh-creator-lifecycle-read-admission-20261014\\\",\\n  \\\"owner\\\": \\\"codex-01a13484-f019-7d82-94ce-812396db9124\\\",\\n  \\\"baseline\\\": {\\n    \\\"head\\\": \\\"0d4ad4f422ec318f1ea9528336e64f0ad4947f87\\\",\\n    \\\"authority_revision\\\": \\\"AOS-002029\\\",\\n    \\\"files\\\": {\\n      \\\".evidence/qyh-creator-lifecycle-read-admission-20261014/plan-review-package-r3.txt\\\": \\\"e91994563cfb15a134d4b4356b249ba13eb4e9ac1f82489daf5c29000cd69163\\\"\\n    }\\n  },\\n  \\\"status\\\": \\\"CONSUMED_MATERIAL_REVIEW\\\",\\n  \\\"execution_authorized\\\": false,\\n  \\\"result_sha256\\\": \\\"f264091a09012711a958acab72c0797e271abef5f699735e827c44924de51e83\\\",\\n  \\\"transport_sha256\\\": \\\"f53c172e0a02e9ac63cdc893c9afcfe53de531f4c5490afb2447fe0fcb1208c3\\\"\\n}\\n\\nFILE services/aos-api/tests/test_ecommerce_workshop_read_http.py SHA256 3f7190e63d8843747ceb5f8e00baa1f336224160f54df03761cef72d3de5ec5e\\n\\\"\\\"\\\"HTTP scope fence: only explicitly audited GETs use installed read admission.\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom fastapi import FastAPI\\nfrom fastapi.testclient import TestClient\\n\\nfrom aos_api.asset_registry.errors import AssetNotFoundError\\nfrom aos_api.auth import Principal, require_principal\\nfrom aos_api.errors import register_exception_handlers\\nfrom aos_api.routers import ecommerce_workshop as routes\\n\\nROOTS = {\\n    'task-cockpit', 'operations', 'content-campaign', 'creator-growth',\\n    'media-studio', 'analyst', 'price-governance', 'customer',\\n}\\n\\n\\nclass RejectingCatalog:\\n    def __init__(self):\\n        self.calls = []\\n\\n    def get_readiness(self, **scope):\\n        self.calls.append(scope)\\n        raise AssetNotFoundError('not installed in current scoped catalog')\\n\\n\\ndef client_with_catalogs():\\n    app = FastAPI()\\n    register_exception_handlers(app)\\n    app.include_router(routes.router)\\n    legacy, reader = RejectingCatalog(), RejectingCatalog()\\n    app.dependency_overrides[routes.get_ecommerce_workshop_catalog] = lambda: legacy\\n    app.dependency_overrides[routes.get_ecommerce_workshop_read_catalog] = lambda: reader\\n    app.dependency_overrides[require_principal] = lambda: Principal(\\n        subject='scope-test', org_id='org-org', project_id='dev-project',\\n        roles=['admin'], markings=[],\\n    )\\n    return TestClient(app), legacy, reader\\n\\n\\n@pytest.mark.parametrize('module', sorted(ROOTS))\\ndef test_root_get_uses_scoped_read_admission_before_business_reader(module):\\n    client, legacy, reader = client_with_catalogs()\\n    response = client.get(f'/v1/ecommerce-workshop/views/{module}')\\n    assert response.status_code == 404\\n    assert not legacy.calls\\n    assert len(reader.calls) == 1\\n    assert reader.calls[0] == dict(module_id=f'ecommerce.{module}',\\n        org_id='org-org', project_id='dev-project', roles=['admin'], markings=[])\\n\\n\\n@pytest.mark.parametrize('path', [\\n    '/views/customer/contributions', '/views/creator-growth/workflow/drafts',\\n    '/modules/ecommerce.operations/readiness',\\n])\\ndef test_unreviewed_get_still_uses_legacy_admission(path):\\n    client, legacy, reader = client_with_catalogs()\\n    response = client.get('/v1/ecommerce-workshop' + path)\\n    assert response.status_code == 404\\n    assert legacy.calls\\n    assert not reader.calls\\n\\n\\ndef test_read_dependency_only_reaches_explicit_audited_get_routes():\\n    actual = set()\\n    for route in routes.router.routes:\\n        uses_read = any(d.call is routes.get_ecommerce_workshop_read_catalog\\n                        for d in route.dependant.dependencies)\\n        if uses_read:\\n            assert route.methods == {'GET'}\\n            actual.add(route.path)\\n    assert actual == {f'/v1/ecommerce-workshop/views/{m}' for m in ROOTS} | {\\n        '/v1/ecommerce-workshop/source-readiness',\\n        '/v1/ecommerce-workshop/views/operations/cases',\\n        '/v1/ecommerce-workshop/commands/operations/readiness',\\n        '/v1/ecommerce-workshop/views/task-cockpit/feedback',\\n        '/v1/ecommerce-workshop/views/task-cockpit/dispatch-scenario',\\n        '/v1/ecommerce-workshop/views/task-cockpit/batch-scenario',\\n        '/v1/ecommerce-workshop/views/media-studio/full-production-scenario',\\n        '/v1/ecommerce-workshop/views/media-studio/workflow/drafts',\\n        '/v1/ecommerce-workshop/views/analyst/learning-scenario',\\n        '/v1/ecommerce-workshop/views/content-campaign/real-inputs',\\n        '/v1/ecommerce-workshop/views/creator-growth/contributions',\\n        '/v1/ecommerce-workshop/views/creator-growth/lifecycle',\\n    }\\n\\n\\ndef test_unknown_query_rejected_before_catalog_call():\\n    client, legacy, reader = client_with_catalogs()\\n    assert client.get('/v1/ecommerce-workshop/views/operations?orgId=dev-org').status_code == 400\\n    assert not legacy.calls and not reader.calls\\n\\n\\nclass ReadReached(RuntimeError):\\n    pass\\n\\n\\ndef test_creator_contribution_read_denied_before_service_access():\\n    client, legacy, reader = client_with_catalogs()\\n    class Service:\\n        def contribution_view(self, scope):\\n            pytest.fail('denied read must not access creator preparation')\\n    client.app.dependency_overrides[routes.get_ecommerce_workshop_creator_prepare] = lambda: Service()\\n    response = client.get('/v1/ecommerce-workshop/views/creator-growth/contributions')\\n    assert response.status_code == 404\\n    assert not legacy.calls\\n    assert reader.calls == [dict(module_id='ecommerce.creator-growth',\\n        org_id='org-org', project_id='dev-project', roles=['admin'], markings=[])]\\n\\n\\ndef test_admitted_cre